import { describe, it } from "vitest";

describe("claim office", () => {
  it.todo("quote with empty item list -> premium 5 G (only the processing fee)");
  it.todo("newcomer quotes a plain sword -> premium 115 G (100 base + 10 first insurance + 5 fee)");
  it.todo("newcomer quotes a plain amulet -> premium 71 G (60 + 6 + 5)");
  it.todo("newcomer quotes a plain staff -> premium 93 G (80 + 8 + 5)");
  it.todo("newcomer quotes a plain potion -> premium 49 G (40 + 4 + 5)");
  it.todo("newcomer quotes a sword and an amulet -> premium 181 G (policy base 160 + 16 + 5)");
  it.todo("newcomer quotes one rune -> premium 33 G (25 + 2.5 + 5 = 32.5 rounded up)");
  it.todo("newcomer quotes 3 runes -> premium 71 G (block base 60 + 6 + 5)");
  it.todo("newcomer quotes 2 runes and 1 moonstone -> premium 88 G (base 75, no block, 87.5 rounded up)");
  it.todo("newcomer quotes a cursed sword -> premium 165 G (100 + 50 curse + 10 first + 5)");
  it.todo("newcomer quotes a cursed sword and a plain amulet -> premium 231 G (curse 50 on sword only: 210 + 16 + 5)");
  it.todo("newcomer quotes a sword with exactly enchantment 5 -> premium 145 G (100 + 30 + 10 + 5)");
  it.todo("customer with exactly 2 years quotes a plain sword -> premium 95 G (100 - 20 loyalty + 10 + 5)");
  it.todo("second quote in a scenario gets follow-up discount -> premiums 115 G then 100 G (100 + 10 - 15 + 5)");
  it.todo("claim on steel sword enchantment 3, damage 500 G -> payout 400 G, remainingCap 1600 G");
  it.todo("claim on rune, damage 200 G -> payout 100 G, remainingCap 400 G (insurance value 250)");
  it.todo("policy with sword and amulet, sword damaged 500 G -> payout 400 G, remainingCap 2800 G (cap 3200)");
  it.todo("claim on staff, damage 300 G -> payout 200 G, remainingCap 1400 G (insurance value 800)");
  it.todo("claim on potion, damage 300 G -> payout 200 G, remainingCap 600 G (insurance value 400)");
  it.todo("claim on moonstone, damage 300 G -> payout 200 G, remainingCap 300 G (insurance value 250)");
  it.todo("dragon attack damages sword 500 G and amulet 300 G -> payout 600 G, remainingCap 2600 G (deductible per item)");
  it.todo("steel sword enchantment 9, damage 1000 G -> payout 400 G, remainingCap 1600 G (50 % then deductible)");
  it.todo("steel sword enchantment 9, damage 901 G -> payout 350 G (350.5 rounded down), remainingCap 1650 G");
  it.todo("two successive 1500 G claims on a sword -> payout 1400 G / remainingCap 600 G, then payout 600 G / remainingCap 0 G");
  it.todo("CLI runs the schema example -> exit 0 and stdout results [{premium 59}, {payout 100, remainingCap 1100}]");
  it.todo("CLI quote with unknown item type broomstick -> non-zero exit, error on stderr, no results on stdout");
  it.todo("CLI claim damaging an amulet when only a sword is insured -> non-zero exit, error on stderr");
  it.todo("CLI claim with two sword damages but only one sword insured -> non-zero exit, whole claim rejected");
  it.todo("CLI claim with damage amount -200 -> non-zero exit, error on stderr");

  describe("verification", () => {
    it.todo("newcomer quotes 2 runes -> premium 60 G (base 50) -- per-component price, item sum");
    it.todo("newcomer quotes 4 runes -> premium 115 G (base 100, block requires exactly 3) -- block rule");
    it.todo("newcomer quotes 7 runes -> premium 198 G (base 175, 197.5 rounded up) -- block rule, rounding up");
    it.todo("newcomer quotes 3 runes and 3 moonstones -> premium 137 G (base 120, two blocks) -- per-type grouping");
    it.todo("newcomer quotes a sword with enchantment 4 -> premium 115 G (no high-enchantment surcharge) -- threshold");
    it.todo("newcomer quotes a cursed sword with enchantment 5 -> premium 195 G (both surcharges) -- curse, enchantment");
    it.todo("newcomer quotes a cursed sword with enchantment 4 -> premium 165 G (curse only) -- curse, threshold");
    it.todo("customer with 1 year quotes a plain sword -> premium 115 G (no loyalty) -- loyalty threshold");
    it.todo("3-year customer's second quote of a cursed sword enchantment 7 -> premium 160 G -- all modifiers");
    it.todo("third quote in a scenario also gets follow-up discount -> premiums 115, 100, 100 G -- follow-up rule");
    it.todo("policy with two swords, both damaged 500 G -> payout 800 G, remainingCap 3200 G (cap 4000) -- per-damage deductible");
    it.todo("dragon-material sword exactly enchantment 8, damage 1000 G -> payout 400 G -- enchantment clause");
    it.todo("dragon-material sword enchantment 9, damage 1000 G -> payout 400 G -- 50 % rule wins");
    it.todo("dragon-material sword enchantment 5, damage 800 G -> payout 700 G, remainingCap 1300 G -- full reimbursement");
    it.todo("cursed sword policy, damage 500 G -> payout 400 G, remainingCap 1600 G (cap from unmodified value) -- cap");
    it.todo("policy with sword and 3 runes, sword damaged 500 G -> payout 400 G, remainingCap 3100 G (sum 1750) -- cap");
    it.todo("two enchantment-9 swords damaged 901 G each -> payout 701 G, remainingCap 3299 G (only final payout rounded)");
    it.todo("claims against two separate sword policies keep separate caps -> each 1500 G claim pays 1400 G, remainingCap 600 G");
    it.todo("CLI claim damaging an unknown item type -> non-zero exit, error on stderr -- not-in-policy check");
  });
});

