export type Item = { type: string; material?: string; enchantment?: number; cursed?: boolean };
export type Damage = { itemType: string; amount: number };
export type QuoteStep = { op: "quote"; items: Item[] };
export type ClaimStep = { op: "claim"; policy: number; incident: { cause: string; damages: Damage[] } };
export type Scenario = { customer: { yearsWithMHPCO: number }; steps: (QuoteStep | ClaimStep)[] };
export type QuoteResult = { premium: number };
export type ClaimResult = { payout: number; remainingCap: number };
export type ScenarioOutput = { results: (QuoteResult | ClaimResult)[] };

const PROCESSING_FEE = 5;
const BASE_PREMIUMS: Record<string, number> = {
  sword: 100,
  amulet: 60,
  staff: 80,
  potion: 40,
  rune: 25,
};
const FIRST_INSURANCE_SURCHARGE_PERCENT = 10;
const PERCENT = 100;

const percentOf = (amount: number, percent: number): number => (amount * percent) / PERCENT;

function quote(items: Item[]): QuoteResult {
  const policyBasePremium = items.reduce((sum, item) => sum + BASE_PREMIUMS[item.type], 0);
  const premium =
    policyBasePremium + percentOf(policyBasePremium, FIRST_INSURANCE_SURCHARGE_PERCENT) + PROCESSING_FEE;
  return { premium: Math.ceil(premium) };
}

export function runScenario(scenario: Scenario): ScenarioOutput {
  return { results: scenario.steps.map((step) => quote((step as QuoteStep).items)) };
}

